<?php
require_once __DIR__.'/http.php';
function mc_asaas_base(): string { return strtolower((string)(getenv('ASAAS_ENVIRONMENT')?:'sandbox'))==='production'?'https://api.asaas.com/v3':'https://api-sandbox.asaas.com/v3'; }
function mc_asaas(string $path,string $method='GET',?array $payload=null): array { $token=(string)getenv('ASAAS_API_KEY');if(!$token)throw new RuntimeException('ASAAS_API_KEY não configurada.');$environment=strtolower((string)(getenv('ASAAS_ENVIRONMENT')?:'sandbox'));$userAgent=trim((string)(getenv('ASAAS_USER_AGENT')?:''));if($userAgent==='')$userAgent='MetalColor/1.0 (PHP; '.$environment.')';$r=mc_http_json(mc_asaas_base().$path,$method,['Accept'=>'application/json','Content-Type'=>'application/json','User-Agent'=>$userAgent,'access_token'=>$token],$payload);if($r['status']<200||$r['status']>=300){$d=$r['data'];$msgs=[];foreach(($d['errors']??[]) as $e)if(isset($e['description']))$msgs[]=$e['description'];throw new RuntimeException($msgs?implode('; ',$msgs):($d['message']??('Asaas HTTP '.$r['status'])),$r['status']);}return $r['data']; }
function mc_checkout_url(string $id): string { $base=strtolower((string)(getenv('ASAAS_ENVIRONMENT')?:'sandbox'))==='production'?'https://asaas.com':'https://sandbox.asaas.com';return $base.'/checkoutSession/show/'.rawurlencode($id); }
